```swift
import Foundation
import Observation

@Observable
final class FeedModel {          // implicitly @MainActor via default isolation
    var items: [Item] = []
    var isLoading = false

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        defer { isLoading = false }

        do {
            items = try await Self.fetchItems(from: feedURL)
        } catch is CancellationError {
            // view went away; nothing to do
        } catch {
            // surface the error, e.g. self.error = error
        }
    }

    @concurrent
    private static func fetchItems(from url: URL) async throws -> [Item] {
        let (data, _) = try await URLSession.shared.data(from: url)
        return Parser.parse(data)
    }
}

// Needed because everything is @MainActor by default:
nonisolated struct Item: Sendable { /* ... */ }

nonisolated enum Parser {        // or nonisolated struct/class
    static func parse(_ data: Data) -> [Item] { /* ... */ }
}
```

Call site:

```swift
struct FeedView: View {
    @State private var model = FeedModel()   // was @StateObject

    var body: some View {
        List(model.items) { /* ... */ }
            .overlay { if model.isLoading { ProgressView() } }
            .task { await model.load() }      // auto-cancelled with the view
    }
}
```

What changed and why:

- **`@Observable` replaces `ObservableObject`/`@Published`.** Views track only the properties they read. In views, `@StateObject` becomes `@State`, and `@ObservedObject` becomes a plain property (or `@Bindable` if you need bindings).
- **No `DispatchQueue` hops.** With main-actor-by-default, `FeedModel` and its mutations are on the main actor, so no `DispatchQueue.main.async` and no `self` capture.
- **`@concurrent` moves the work off the main actor.** Under Swift 6.2's approachable concurrency, a plain `async` function stays on the caller's actor, so without `@concurrent` the parsing would run on the main thread. It's `static` so it can't touch main-actor state, and the URL is passed in rather than read from a main-actor global.
- **`URLSession.shared.data(from:)` replaces `Data(contentsOf:)`.** The old call blocked a thread on network I/O. The new one is non-blocking and cancellable.
- **`try!` is gone.** Errors are handled instead of crashing.
- **`nonisolated` and `Sendable` on `Parser` and `Item`.** Under default main-actor isolation they'd otherwise be main-actor-isolated, and the compiler would reject calling `Parser.parse` from the `@concurrent` function. `Item` must be `Sendable` to cross back to the main actor.

If `feedURL` is a global, it's also main-actor-isolated by default. That's fine here, since `load()` runs on the main actor and passes it in. If you want it usable anywhere, declare it `nonisolated let feedURL = URL(...)`.

```swift
import Foundation
import Observation

// Under main-actor-by-default, these must opt out so they can run off the main actor.
nonisolated struct Item: Sendable { /* ... */ }

nonisolated enum Parser {
    static func parse(_ data: Data) throws -> [Item] { /* ... */ }
}

@Observable
final class FeedModel {          // implicitly @MainActor
    var items: [Item] = []
    var isLoading = false
    var error: Error?

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        defer { isLoading = false }

        do {
            items = try await Self.fetchItems(from: feedURL)
        } catch is CancellationError {
            // view went away; nothing to do
        } catch {
            self.error = error
        }
    }

    @concurrent
    nonisolated private static func fetchItems(from url: URL) async throws -> [Item] {
        let (data, _) = try await URLSession.shared.data(from: url)
        return try Parser.parse(data)   // CPU work stays off the main actor
    }
}
```

Call it from SwiftUI like this:

```swift
struct FeedView: View {
    @State private var model = FeedModel()

    var body: some View {
        List(model.items) { /* ... */ }
            .overlay { if model.isLoading { ProgressView() } }
            .task { await model.load() }   // cancelled automatically when the view disappears
    }
}
```

**What changed and why**

- **`ObservableObject` and `@Published` became `@Observable`.** Views now track only the properties they actually read. Use `@State` to own the model instead of `@StateObject`.
- **No explicit `@MainActor`.** With main-actor-by-default, `FeedModel` and its mutations are already isolated to the main actor. This removes the `DispatchQueue.main.async` hop and the `self` capture.
- **`DispatchQueue.global().async` became an `async` function with `@concurrent`.** `@concurrent` explicitly runs the function on the global executor. Without it, under Swift 6.2's `nonisolated(nonsending)` default, a nonisolated async function would stay on the caller's actor, which is the main actor here.
- **`Data(contentsOf:)` became `URLSession.shared.data(from:)`.** The old call blocked a thread on network I/O. The new one suspends instead and supports cancellation.
- **`try!` is gone.** Errors are stored in `error` so the UI can show them. Previously a bad feed would crash the app.
- **Added `guard !isLoading` and `defer`.** This prevents overlapping loads and guarantees `isLoading` resets on every exit path.
- **Marked `Item` and `Parser` as `nonisolated`.** With main-actor-by-default they would otherwise be main-actor-isolated, and calling them from the `@concurrent` function would be an isolation error or would hop back to the main actor. `Item` must also be `Sendable` to cross back from the background work.

If `feedURL` is a global, it is also main-actor-isolated by default. Reading it in `load()` is fine, since that runs on the main actor, and it is then passed as a parameter. If you want to use it from nonisolated code directly, declare it `nonisolated let`.

