# Rate limiter design

## Decisions up front

- **Algorithm:** sliding window counter. It keeps two fixed-window counters per key and weights the previous one by how much of it still overlaps the window. It uses O(1) memory per key and avoids the 2x boundary burst of a plain fixed window. The count is approximate, which is fine for 100/min.
- **Atomicity:** one Redis Lua script does read, compute, and increment in a single round trip. Without it, 4 instances will race and over-admit.
- **Clock:** the script uses Redis `TIME`, not `Date.now()` on the instances, so skew between servers can't affect window boundaries.
- **Layering:** the store knows nothing about HTTP, and the middleware knows nothing about Redis. This makes the algorithm testable with an in-memory fake.
- **Failure mode:** configurable fail-open or fail-closed when Redis is unreachable.

## Types

```ts
// ---- Core domain ----

export interface RateLimitPolicy {
  limit: number;        // max requests per window, e.g. 100
  windowMs: number;     // e.g. 60_000
}

export interface RateLimitDecision {
  allowed: boolean;
  limit: number;
  remaining: number;           // never negative
  resetAfterMs: number;        // until the budget is fully restored
  retryAfterMs: number | null; // null when allowed
}

// ---- Storage boundary ----

export interface RateLimitStore {
  /** Atomically record `cost` requests against `key` and return the decision. */
  consume(key: string, policy: RateLimitPolicy, cost?: number): Promise<RateLimitDecision>;
}

export interface RedisStoreOptions {
  keyPrefix?: string;  // default "rl"
}

export function createRedisStore(
  redis: RedisClientLike,   // ioredis / node-redis, whichever you use
  options?: RedisStoreOptions
): RateLimitStore;

// Minimal surface the store needs, so tests can fake it
export interface RedisClientLike {
  evalsha(sha: string, numKeys: number, ...args: (string | number)[]): Promise<unknown>;
  script(subcommand: "LOAD", script: string): Promise<string>;
}

// ---- Limiter (policy + keying + failure handling) ----

export type FailureMode = "fail-open" | "fail-closed";

export interface RateLimiterOptions<Ctx> {
  store: RateLimitStore;
  /** Pull the identity out of the request context; return null if absent. */
  getKey: (ctx: Ctx) => string | null;
  /** Static policy or per-key resolver (leaves room for tiers later). */
  policy: RateLimitPolicy | ((key: string, ctx: Ctx) => RateLimitPolicy | Promise<RateLimitPolicy>);
  onStoreError?: FailureMode;                       // default "fail-open"
