}

export function rateLimitMiddleware(opts: RateLimitMiddlewareOptions): RequestHandler;

/** Pure function, easy to unit test. */
export function decisionToHeaders(d: RateLimitDecision): Record<string, string>;
```

`IncomingRequestLike` and `RequestHandler` stand in for your framework's types (Express, Fastify, etc.).

