export type ApiKeyId = string & { readonly __brand: "ApiKeyId" };
export const asApiKeyId = (raw: string): ApiKeyId => { throw new Error("not implemented"); }; // validates non-empty, bounded length

export interface Policy {
  readonly limit: number;     // > 0, integer
  readonly windowMs: number;  // > 0, integer
}

export type Decision =
  | { readonly allowed: true;  readonly remaining: number; readonly resetAfterMs: number }
  | { readonly allowed: false; readonly retryAfterMs: number };

export interface RateLimiter {
  /** Consumes one unit for `key`. Atomic across all instances. Never throws; store failures follow onStoreError. */
  check(key: ApiKeyId): Promise<Decision>;
}

export interface RateLimiterConfig {
  readonly redis: RedisLike;                       // minimal structural type: only evalsha/script load
  readonly policy: Policy;
  readonly onStoreError: "fail-open" | "fail-closed";
  readonly keyPrefix?: string;                     // default "rl:"
}

export function createRateLimiter(config: RateLimiterConfig): RateLimiter;
```

```ts
// ---- rate-limiter/redis-store.ts (private) ----
interface ScriptReply { allowed: 0 | 1; remaining: number; retryAfterMs: number; resetAfterMs: number }

/** One round trip. Script reads Redis TIME, so no instance clock is involved. */
function runGcra(redis: RedisLike, redisKey: string, policy: Policy): Promise<ScriptReply>;
function toDecision(reply: ScriptReply): Decision;   // wire type → domain type; ScriptReply never leaves this file
```

```ts
