  | { allowed: true;  remaining: number; resetMs: number }
  | { allowed: false; remaining: 0;      resetMs: number; retryAfterMs: number };

export interface RateLimiter {
  /** Atomically counts this request against `apiKey` and returns the verdict. Never throws:
   *  Redis failures are resolved by `onRedisError`. */
