  policy: Policy;
  onRedisError: "fail-open" | "fail-closed";
  keyPrefix?: string;           // default "rl:"
}

export function createRateLimiter(config: RateLimiterConfig): RateLimiter;

/** Minimal slice of the Redis client we need. This keeps ioredis/node-redis types out of the API. */
export interface ScriptRunner {
  evalsha(sha: string, keys: string[], args: (string | number)[]): Promise<unknown>;
  script(cmd: "LOAD", src: string): Promise<string>;
}

// ---- public: middleware.ts (thin HTTP adapter) ----

export function rateLimitMiddleware(limiter: RateLimiter): express.RequestHandler;
// reads the ApiKey set by auth; on deny -> 429 + Retry-After, RateLimit-Remaining, RateLimit-Reset

// ---- private: slidingWindowScript.ts ----

/** Lua, runs atomically in Redis:
 *  - now = redis.call('TIME')              (single clock for all 4 instances)
 *  - ZREMRANGEBYSCORE key -inf (now - windowMs)
 *  - if ZCARD + cost <= limit -> ZADD, PEXPIRE key windowMs -> allowed
 *  - else compute retryAfter from oldest entry's score
 *  Returns [allowed, remaining, resetMs, retryAfterMs]. */
const SCRIPT: string;
function parseReply(raw: unknown): Decision;   // wire tuple -> domain type
```

- **Hidden:** the algorithm, the Redis key layout, the Lua script, the clock source, script loading and `NOSCRIPT` recovery, and the failure policy.
- **Exposed:** one method and one result type.
- **Validation:** `Policy` and `cost` are checked at the boundary. Inside, the types are trusted.
- **Sliding window log (ZSET):** this gives exact "no more than 100 in any 60 s" semantics, and the whole decision is a single atomic script call. Each key holds at most about 100 members, which is small.
- **No local state:** the 4 instances share nothing except Redis, so no locks or coordination are needed.

## Synthesis decision
I chose the sliding-window log over two alternatives.

- **Fixed-window `INCR`+`EXPIRE`:** it's the smallest option. It allows up to 200 requests across a window boundary, and `retryAfter` is only approximate.
- **Token bucket (hash with tokens and timestamp):** it's also one Lua call and uses less memory. It allows a burst of 100 and then refills slowly, which isn't what "100 per minute" says to most API consumers.

All three fit behind the same `RateLimiter` interface, so the choice can change later without touching any callers.

## Tradeoffs accepted
- **Memory:** about 100 ZSET entries per active key, in exchange for exact semantics.
- **Latency:** one Redis round trip per request. There's no local caching, so limits are never overshot.
- **Single Redis:** if you run Redis Cluster, a key hashes to one slot, so the single-key script is fine.

