import { chromium } from 'playwright';

const BASE = 'http://localhost:3000';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

try {
  await page.goto(`${BASE}/login`);

  const email = page.getByLabel(/email/i)
    .or(page.getByPlaceholder(/email/i))
    .or(page.locator('input[type="email"], input[name="email"]'))
    .first();
  const password = page.getByLabel(/password/i)
    .or(page.getByPlaceholder(/password/i))
    .or(page.locator('input[type="password"]'))
    .first();

  await email.fill('demo@example.com');
  await password.fill('demo');

  await Promise.all([
    page.waitForURL(url => !url.pathname.startsWith('/login'), { timeout: 15000 }),
    page.getByRole('button', { name: /log\s?in|sign\s?in|submit/i }).first().click(),
  ]);

  await page.goto(`${BASE}/dashboard`);
  await page.waitForLoadState('networkidle');
  await page.screenshot({ path: 'dash.png', fullPage: true });
  console.log('Saved dash.png');
} catch (e) {
  await page.screenshot({ path: 'error.png', fullPage: true }).catch(() => {});
  console.error('Failed (see error.png):', e.message);
  process.exitCode = 1;
} finally {
  await browser.close();
}
```

**Run:**
```bash
node shot.mjs
```

- **Login not redirecting:** if your app logs in without leaving `/login`, for example through a SPA state change, the `waitForURL` will time out. Replace it with a wait for something that only appears after login.
- **Failures:** the script saves `error.png` so you can see what the page looked like.
- **Dashboard still loading:** if the dashboard loads data slowly or polls, `networkidle` may fire too early or never. Wait for a specific element instead, for example `await page.getByRole('heading', { name: /dashboard/i }).waitFor()`.
- **Visible browser:** use `chromium.launch({ headless: false })` to watch it run.

