```js
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });

  await page.goto('http://localhost:3000/login');

  // Email: try label first, fall back to common input selectors
  const email = page.getByLabel(/email/i).or(page.locator('input[type="email"], input[name="email"]')).first();
  const password = page.getByLabel(/password/i).or(page.locator('input[type="password"]')).first();

  await email.fill('demo@example.com');
  await password.fill('demo');

  await Promise.all([
    page.waitForURL(url => !url.pathname.startsWith('/login'), { timeout: 15000 }),
    page.locator('button[type="submit"]').or(page.getByRole('button', { name: /log\s?in|sign\s?in/i })).first().click(),
  ]);

  await page.goto('http://localhost:3000/dashboard');
  await page.waitForLoadState('networkidle');

  await page.screenshot({ path: 'dash.png', fullPage: true });
  await browser.close();
  console.log('Saved dash.png');
})().catch(err => { console.error(err); process.exit(1); });
```

**Run:**
```bash
node dash-shot.js
```

Notes:
- The login step waits for the URL to leave `/login`. If your app stays on `/login` after a successful login, replace that wait with `page.waitForResponse(...)` or wait for an element that only appears when you're logged in.
- If the screenshot shows the login page, the login failed or the session cookie wasn't set. Add `headless: false` to `chromium.launch()` to watch it run.
- If the dashboard loads content lazily on scroll, a full-page screenshot may show blank sections. Scroll the page first, or wait for a specific selector before the screenshot.

