```tsx
import {AbsoluteFill, Series, interpolate, spring, useCurrentFrame, useVideoConfig} from 'remotion';

const ACCENT = '#6C5CE7'; // swap for your brand color
const BG = '#0B0D12';
const font = 'Inter, system-ui, sans-serif';

const Center: React.FC<{children: React.ReactNode; bg?: string}> = ({children, bg = BG}) => (
  <AbsoluteFill style={{background: bg, color: 'white', fontFamily: font, justifyContent: 'center', alignItems: 'center'}}>
    {children}
  </AbsoluteFill>
);

// Scene 1: the mistake being typed
const Hook: React.FC = () => {
  const frame = useCurrentFrame();
  const text = 'DELETE FROM orders;';
  const chars = Math.min(text.length, Math.floor(frame / 3));
  const cursor = Math.floor(frame / 15) % 2 === 0 ? '▌' : ' ';
  return (
    <Center>
      <div style={{fontFamily: 'monospace', fontSize: 72}}>
        <span style={{color: '#888'}}>&gt; </span>
        {text.slice(0, chars)}
        {cursor}
      </div>
    </Center>
  );
};

// Scene 2: rows disappear
const Disaster: React.FC = () => {
  const frame = useCurrentFrame();
  const rows = Math.round(interpolate(frame, [20, 60], [48213, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'}));
  const red = interpolate(frame, [55, 65, 90], [0, 0.35, 0.15], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  return (
    <Center bg={`rgba(${Math.round(11 + red * 230)}, 13, 18, 1)`}>
      <div style={{fontSize: 36, opacity: 0.6}}>orders</div>
      <div style={{fontSize: 200, fontWeight: 800}}>{rows.toLocaleString()}</div>
      <div style={{fontSize: 36, opacity: 0.6}}>rows</div>
    </Center>
  );
};

// Scene 3: title card
const Title: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const s = spring({frame, fps, config: {damping: 12}});
  return (
    <Center>
      <div style={{fontSize: 180, fontWeight: 800, transform: `scale(${0.8 + 0.2 * s})`, opacity: s}}>
        <span style={{color: ACCENT}}>Snap</span>shots
      </div>
    </Center>
  );
};

// Scene 4: timeline scrubber
const Timeline: React.FC = () => {
  const frame = useCurrentFrame();
  const progress = interpolate(frame, [30, 330], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const eased = 1 - Math.pow(1 - progress, 3);
  const minutesAgo = Math.round(eased * 4000); // up to ~2.8 days back
  const days = Math.floor(minutesAgo / 1440);
  const hrs = Math.floor((minutesAgo % 1440) / 60);
  const mins = minutesAgo % 60;
  const barW = 1400;
  const x = barW * (1 - (minutesAgo / (7 * 1440)));
  return (
    <Center>
      <div style={{fontSize: 64, fontWeight: 700, marginBottom: 80}}>Any minute. Last 7 days.</div>
      <div style={{width: barW, height: 12, background: '#222736', borderRadius: 6, position: 'relative'}}>
        <div style={{position: 'absolute', left: x, right: 0, top: 0, bottom: 0, background: '#2c3350', borderRadius: 6}} />
        <div style={{position: 'absolute', left: x - 20, top: -14, width: 40, height: 40, borderRadius: 20, background: ACCENT, boxShadow: `0 0 40px ${ACCENT}`}} />
        <div style={{position: 'absolute', left: 0, top: 40, opacity: 0.5, fontSize: 28}}>7 days ago</div>
        <div style={{position: 'absolute', right: 0, top: 40, opacity: 0.5, fontSize: 28}}>Now</div>
      </div>
      <div style={{marginTop: 140, fontSize: 56, fontFamily: 'monospace'}}>
        Restore to: now − {days}d {hrs}h {mins}m
      </div>
    </Center>
  );
};

// Scene 5: restored
const Restore: React.FC = () => {
  const frame = useCurrentFrame();
  const rows = Math.round(interpolate(frame, [30, 90], [0, 48213], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'}));
  const done = frame >= 90;
  return (
    <Center>
      <div style={{fontSize: 36, opacity: 0.6}}>orders</div>
      <div style={{fontSize: 200, fontWeight: 800, color: done ? '#2ECC71' : 'white'}}>{rows.toLocaleString()}</div>
      <div style={{fontSize: 48, opacity: done ? 1 : 0}}>✓ Restored</div>
    </Center>
  );
};

// Scene 6: CTA
const CTA: React.FC = () => {
  const frame = useCurrentFrame();
  const o = interpolate(frame, [0, 20], [0, 1], {extrapolateRight: 'clamp'});
  return (
    <Center>
      <div style={{opacity: o, textAlign: 'center'}}>
        <div style={{fontSize: 120, fontWeight: 800}}>Snapshots</div>
        <div style={{fontSize: 48, margin: '30px 0', opacity: 0.7}}>Available today</div>
        <div style={{display: 'inline-block', background: ACCENT, padding: '24px 56px', borderRadius: 16, fontSize: 48, fontWeight: 600}}>
          Try Snapshots → yourdomain.com/snapshots
        </div>
      </div>
    </Center>
  );
};

export const Launch: React.FC = () => (
  <Series>
    <Series.Sequence durationInFrames={150}><Hook /></Series.Sequence>
    <Series.Sequence durationInFrames={150}><Disaster /></Series.Sequence>
    <Series.Sequence durationInFrames={150}><Title /></Series.Sequence>
    <Series.Sequence durationInFrames={450}><Timeline /></Series.Sequence>
    <Series.Sequence durationInFrames={240}><Restore /></Series.Sequence>
    <Series.Sequence durationInFrames={210}><CTA /></Series.Sequence>
  </Series>
);
```

